(async () => {
  const rows = await FileAttachment("sales.csv").csv({typed: true});
  const fmt = d3.utcFormat("%b");
  const by = d3.rollups(rows.filter(r => new Date(r.date).getUTCFullYear() === 2025),
    v => d3.sum(v, r => r.revenue), r => new Date(r.date).getUTCMonth());
  const data = by.sort((a,b)=>a[0]-b[0]).map(([m,v]) => ({month: fmt(new Date(Date.UTC(2025,m,1))), revenue: v}));
  return Plot.plot({
    width: 800, height: 420, marginLeft: 70, style: {fontSize: "14px", background: "white"},
    title: "Monthly revenue, 2025",
    x: {domain: data.map(d=>d.month), label: null},
    y: {label: "Revenue ($)", grid: true, tickFormat: "s"},
    marks: [Plot.lineY(data, {x: "month", y: "revenue", stroke: "#2563eb", strokeWidth: 2.5}),
      Plot.dot(data, {x: "month", y: "revenue", fill: "#2563eb", r: 5}),
      Plot.ruleY([0])]
  });
})()

{
  const data = [{ task: "meetings", value: 30 }, { task: "coding", value: 50 }, { task: "review", value: 20 }];
  const w = 360, r = 150;
  const color = d3.scaleOrdinal(data.map(d => d.task), d3.schemeTableau10);
  const arcs = d3.pie().sort(null).value(d => d.value)(data);
  const arc = d3.arc().innerRadius(0).outerRadius(r);
  const label = d3.arc().innerRadius(r * 0.65).outerRadius(r * 0.65);
  const svg = d3.create("svg").attr("viewBox", [-w / 2, -w / 2, w, w]).attr("width", w).attr("height", w);
  svg.selectAll("path").data(arcs).join("path")
    .attr("d", arc).attr("fill", d => color(d.data.task)).attr("stroke", "white");
  svg.selectAll("text").data(arcs).join("text")
    .attr("transform", d => `translate(${label.centroid(d)})`)
    .attr("text-anchor", "middle").attr("fill", "white").attr("font-size", 14)
    .text(d => `${d.data.task} ${d.data.value}%`);
  return svg.node();
}

